INSERT INTO knowledge.source_claim (claim_id, claim_code, source_version_id, chapter_id, chunk_id, page_start, page_end, claim_type, claim_kind, claim_text, knowledge_type, contract, confidence, status) VALUES
   ('f706718d-7eda-5879-8965-ae6c0916f630', 'HCH13-0001', 'HUTCHISON_24_2018', 'H1-C13', '019e65f6-2e79-5987-a4cf-f0a1b6b52068', '193', '193', 'CARDIOVASCULAR_METHOD', 'definition', 'Congestive heart failure - typical patient: middle-aged (male) or elderly (either sex) patient with a history of myocardial infarction or long-standing hypertension; in cases where there is no clear cause, always enquire about alcohol consumption. Major symptoms: exertional fatigue and shortness of breath, with orthopnoea and paroxysmal nocturnal dyspnoea in advanced cases. Major signs: fluid retention - basal crackles, raised JVP, peripheral oedema; reduced cardiac output - cool skin, peripheral cyanosis; other findings - third heart sound.', 'medicine', '{"what_is_it":"Congestive heart failure clinical features (Box 13.10)","what_fact_produces":"DYSPNOEA_PRESENT, ORTHOPNOEA, PND, PERIPHERAL_OEDEMA, CRACKLES, JUGULAR_VENOUS_DISTENTION","source_support":"Hutchison 24e p193"}'::jsonb, 0.9, 'VERIFIED'),
   ('58ec967e-975f-55f0-80b5-6893845b7bd6', 'HCH13-0002', 'HUTCHISON_24_2018', 'H1-C13', '019e65f6-2e79-5987-a4cf-f0a1b6b52068', '193', '193', 'CARDIOVASCULAR_METHOD', 'investigation', 'Congestive heart failure diagnosis - ECG: usually abnormal, often showing Q waves (previous myocardial infarction), left ventricular hypertrophy (hypertension) or left bundle branch block (LBBB); chest X-ray: cardiac enlargement with congested lung fields; echocardiogram: left ventricular dilatation with regional (coronary heart disease) or global (cardiomyopathy) contractile impairment; raised B-type natriuretic peptide (BNP) useful in cases of diagnostic uncertainty; renal function as prelude to diuretic and angiotensin converting enzyme (ACE) inhibitor therapy; blood count to rule out anaemia. The echocardiogram is the single most important diagnostic test in the patient with heart failure.', 'medicine', '{"what_is_it":"Congestive heart failure diagnosis + investigations (Box 13.10)","what_connects_to":"INV-ECG, INV-CXR, INV-ECHO, INV-BNP, INV-UREA-CREAT, INV-FBC","source_support":"Hutchison 24e p193"}'::jsonb, 0.9, 'VERIFIED'),
   ('d55e88ee-a07a-5793-8265-273d250cb037', 'HCH13-0003', 'HUTCHISON_24_2018', 'H1-C13', '019e65f6-2e79-5987-a4cf-f0a1b6b52068', '193', '193', 'CARDIOVASCULAR_METHOD', 'threshold', 'New York Heart Association (NYHA) classification of breathlessness in heart failure (Table 13.2): Class I - asymptomatic; Class II - symptoms on normal exertion, e.g. walking up a flight of stairs; Class III - symptoms on minimal exertion, e.g. getting dressed; Class IV - symptoms at rest.', 'medicine', '{"what_is_it":"NYHA functional classification","what_fact_produces":"DYSPNOEA_AT_REST, DYSPNOEA_ON_MINIMAL_EXERTION, DYSPNOEA_ON_NORMAL_EXERTION","source_support":"Hutchison 24e p193 (Table 13.2)"}'::jsonb, 0.9, 'VERIFIED'),
   ('96f1e283-5f23-5145-959a-50e38fbb989d', 'HCH13-0004', 'HUTCHISON_24_2018', 'H1-C13', '019e65f6-2e79-5987-a4cf-f0a1b6b52068', '193', '193', 'CARDIOVASCULAR_METHOD', 'red_flag', 'Acute left ventricular failure - typical patient: acute myocardial infarction or known left ventricular disease. Major symptoms: severe dyspnoea, orthopnoea, frothy sputum. Major signs: low-output state (hypotension, oliguria, cold periphery), tachycardia, S3, sweating, crackles at lung bases. Diagnosis: chest X-ray shows bilateral air space consolidation with typical perihilar distribution; echocardiogram usually confirms left ventricular disease; ECG may show evidence of acute or previous myocardial infarction; blood gas analysis shows variable hypoxaemia. Vital to exclude valvular disease which is potentially correctable by surgery.', 'medicine', '{"what_is_it":"Acute left ventricular failure presentation (Box 13.9)","what_fact_produces":"DYSPNOEA_PRESENT, ORTHOPNOEA, CRACKLES","what_connects_to":"INV-ECG, INV-CXR, INV-ECHO","source_support":"Hutchison 24e p193 (Box 13.9)"}'::jsonb, 0.9, 'VERIFIED'),
   ('e0edbe97-600c-52ba-b922-7fde54fad8f9', 'HCH13-0005', 'HUTCHISON_24_2018', 'H1-C13', '7ac14d53-c395-5ca0-97d4-826c5d692565', '196', '196', 'CARDIOVASCULAR_METHOD', 'examination', 'Subcutaneous oedema that pits on digital pressure is a cardinal feature of congestive heart failure; pressure should be applied over a bony prominence (tibia, lateral malleoli, sacrum). Oedema is caused by salt and water retention by the kidney: reduced sodium delivery to the nephron (from constriction of preglomerular arterioles in response to sympathetic activation and angiotensin II) and increased sodium reabsorption (proximal tubule early in failure; later renin-angiotensin activation stimulates aldosterone, increasing distal sodium reabsorption). Salt and water retention expands plasma volume and capillary hydrostatic pressure so fluid accumulates in the interstitial space; oedema is most prominent around the ankles in the ambulant patient and over the sacrum in the bedridden patient, and may involve legs, genitalia and trunk in advanced failure, with ascites and pleural/pericardial transudation.', 'medicine', '{"what_is_it":"Pitting oedema - cardinal feature of congestive heart failure + mechanisms","what_fact_produces":"PERIPHERAL_OEDEMA","source_support":"Hutchison 24e p196"}'::jsonb, 0.9, 'VERIFIED'),
   ('a98a7729-9a05-55b1-af46-1c676edd1ead', 'HCH13-0006', 'HUTCHISON_24_2018', 'H1-C13', '959fd9ed-86c8-56df-9fa0-ba6e67cf6964', '198', '198', 'CARDIOVASCULAR_METHOD', 'examination', 'The jugular venous pressure (JVP) is assessed from the waveform of the internal jugular vein adjacent to the medial border of the sternocleidomastoid muscle; distension of the external jugular vein is a useful clue to an elevated JVP. It is measured in centimetres vertically from the sternal angle to the top of the venous waveform; the normal upper limit is 4 cm (about 9 cm above the right atrium, corresponding to 6 mmHg). Elevation of the JVP indicates a raised right atrial pressure unless the superior vena cava is obstructed. Causes of elevated JVP (Box 13.12) include congestive heart failure, cor pulmonale, pulmonary embolism, right ventricular infarction, tricuspid valve disease, tamponade, constrictive pericarditis, hypertrophic/restrictive cardiomyopathy, superior vena cava obstruction and iatrogenic fluid overload.', 'medicine', '{"what_is_it":"Jugular venous pressure assessment + causes of elevated JVP (Box 13.12)","what_fact_produces":"JUGULAR_VENOUS_DISTENTION","source_support":"Hutchison 24e p198 (Box 13.12)"}'::jsonb, 0.9, 'VERIFIED'),
   ('6f419b30-af78-57a2-a887-26b68872bf3a', 'HCH9-0001', 'HUTCHISON_24_2018', 'H1-C09', '22bc3a24-79d6-526b-91bb-3dbee146ba26', '123', '123', 'EMERGENCY_METHOD', 'red_flag', 'In the emergency patient, a raised jugular venous pressure may suggest early heart failure; precordial auscultation may reveal a pericardial rub. Important examination features in the initial rapid assessment include the fine crepitations of pulmonary oedema, the hyperresonant percussion and tracheal deviation of pneumothorax, and asymmetric blood pressure readings consistent with thoracic aortic dissection.', 'medicine', '{"what_is_it":"Raised JVP may suggest early heart failure; fine crepitations of pulmonary oedema","what_fact_produces":"JUGULAR_VENOUS_DISTENTION, CRACKLES","source_support":"Hutchison 24e p123"}'::jsonb, 0.9, 'VERIFIED'),
   ('cd3a0152-7bff-526b-a795-5b454d53d3ca', 'HCH9-0002', 'HUTCHISON_24_2018', 'H1-C09', '3126b5c6-8d52-5a42-9cb9-2a48293eabba', '124', '124', 'EMERGENCY_METHOD', 'management', 'The breathless patient should be placed in a safe, monitored (ECG and pulse oximetry) environment; act quickly if there is visible distress, use of accessory muscles, high respiratory rate, high pulse rate, cyanosis or low oxygen saturations. The immediate response is to administer high-flow oxygen unless there is good evidence that this has, on this or previous occasions, caused breathing difficulties (most commonly chronic obstructive pulmonary disease). In most cases arrangements for urgent ECG and chest X-ray (CXR) will be made immediately, before the initial clinical assessment is complete. Pulmonary oedema is among the potentially life-threatening conditions presenting as breathlessness (Table 9.4). In chest pain, troponin is measured in blood (released when cardiac myocytes undergo ischaemic necrosis); a negative result indicates the risk of a serious acute cardiac event in the ensuing 30 days is extremely low.', 'medicine', '{"what_is_it":"Breathless patient: monitored environment, high-flow O2 unless COPD, urgent ECG + CXR","what_connects_to":"INV-ECG, INV-CXR, INV-TROPONIN, MON-SPO2","source_support":"Hutchison 24e p124 (Table 9.4)"}'::jsonb, 0.9, 'VERIFIED'),
   ('d6420ee4-e7d9-536d-a3cd-c01fd817f4f9', 'HCH9-0003', 'HUTCHISON_24_2018', 'H1-C09', 'bc7582d0-879d-53aa-b4e7-7c4e935252bb', '129', '129', 'EMERGENCY_METHOD', 'red_flag', 'Cardiogenic shock is a failure of the heart to pump blood effectively to meet peripheral oxygen demands, most frequently due to a large myocardial infarction but also to cardiac dysrhythmias, other causes of cardiac muscle pump failure (myocarditis, cardiomyopathy) or acute cardiac valve problems. There is usually a narrow pulse pressure; it may be associated with preceding chest pain, palpitations or breathlessness (in particular orthopnoea), and there are frequently auscultatory features of pulmonary oedema. An ECG is often informative and may show changes of recent infarction, dysrhythmia or nonspecific changes of pericarditis, myocarditis and cardiomyopathy. Treatment largely depends on the cause; inotropic support and invasive measures are frequently required.', 'medicine', '{"what_is_it":"Cardiogenic shock - presentation and escalation","what_connects_to":"REF-CRITICAL-CARE, INV-ECG","source_support":"Hutchison 24e p129"}'::jsonb, 0.9, 'VERIFIED'),
   ('8a6b240b-3ec8-5bd5-950e-15fad4c9a6b4', 'KCR-0019', 'KUMAR_CLARK_10_2017', 'KC-C28', '8015cb33-f797-5c8a-aeaf-c4e37beafd95', '929', '929', 'RESPIRATORY_METHOD', 'investigation', 'On the chest X-ray, heart size should be less than 50% of the thoracic width on a PA chest film; assess the heart borders. Cardiomegaly may be caused by hypertension, valvular disease, heart failure or cardiomyopathy. Interstitial changes may be caused by pulmonary oedema or fibrosis; loss of the costophrenic angle is usually due to pleural effusions.', 'medicine', '{"what_is_it":"CXR interpretation: heart size <50% thoracic width; cardiomegaly causes","what_connects_to":"INV-CXR","source_support":"Kumar & Clark 10e p929"}'::jsonb, 0.9, 'VERIFIED'),
   ('55213128-67ac-5489-99db-9c96ecafcf74', 'KCR-0020', 'KUMAR_CLARK_10_2017', 'KC-C28', '68e27abe-86b4-5d63-926e-03a6126046ba', '937', '937', 'RESPIRATORY_METHOD', 'definition', 'Orthopnoea is breathlessness on lying down; while classically linked to heart failure it is partly due to the weight of the abdominal contents pushing the diaphragm up into the thorax. Paroxysmal nocturnal dyspnoea (PND) describes acute episodes of breathlessness at night, typically due to heart failure. Breathlessness can be graded using the Medical Research Council (MRC) grading of dyspnoea (Box 28.5).', 'medicine', '{"what_is_it":"Orthopnoea and paroxysmal nocturnal dyspnoea - typically due to heart failure","what_fact_produces":"ORTHOPNOEA, PND","source_support":"Kumar & Clark 10e p937"}'::jsonb, 0.9, 'VERIFIED')
INSERT INTO knowledge.condition (id, concept_id, condition_code, canonical_name, description, condition_type, status) VALUES
   ('77d87c89-f3b3-5f04-864c-19f5f7efa6e1', NULL, 'COND-HF-DECOMPENSATION', 'Heart failure decompensation', 'Acute worsening of heart failure with congestion (dyspnoea, orthopnoea, paroxysmal nocturnal dyspnoea, peripheral oedema, raised JVP, basal crackles) and/or low cardiac output (fatigue, cool periphery, hypotension), most often on a background of ischaemic or hypertensive left ventricular disease; severe cases present as acute left ventricular failure or cardiogenic shock.', 'acute', 'active')
