   ('7206beea-a7b3-5043-a134-6b5ce3534412', (SELECT id FROM knowledge.phenotype WHERE phenotype_code = 'PHEN-ACUTE-HYPOXAEMIC'), (SELECT id FROM knowledge.condition WHERE condition_code = 'COND-HF-DECOMPENSATION'), 'associated', '0.40'),
   ('d1b1fdad-b2b7-5a09-95fd-74065c8ca8f2', (SELECT id FROM knowledge.phenotype WHERE phenotype_code = 'PHEN-RESPIRATORY-FAILURE'), (SELECT id FROM knowledge.condition WHERE condition_code = 'COND-HF-DECOMPENSATION'), 'associated', '0.50')
