INSERT INTO knowledge.severity_score_component (id, score_id, component_code, component_name, condition, points, rationale, sort_order) VALUES
   ('f330b9bb-428c-5681-9f0e-aeb5ee33bc3d', (SELECT id FROM knowledge.severity_score WHERE score_code = 'SCORE-NYHA'), 'NYHA-1', 'NYHA I - Asymptomatic', '{"type":"and","conditions":[{"type":"not","condition":{"type":"boolean","fact_code":"DYSPNOEA_AT_REST","expect":true}},{"type":"not","condition":{"type":"boolean","fact_code":"DYSPNOEA_ON_MINIMAL_EXERTION","expect":true}},{"type":"not","condition":{"type":"boolean","fact_code":"DYSPNOEA_ON_NORMAL_EXERTION","expect":true}}]}'::jsonb, '1', 'No dyspnoea on ordinary exertion; asymptomatic (HCH13-0003).', '10'),
   ('13136253-91cb-5a7f-9f8b-c5e509963f76', (SELECT id FROM knowledge.severity_score WHERE score_code = 'SCORE-NYHA'), 'NYHA-2', 'NYHA II - Symptoms on normal exertion', '{"type":"and","conditions":[{"type":"boolean","fact_code":"DYSPNOEA_ON_NORMAL_EXERTION","expect":true},{"type":"not","condition":{"type":"boolean","fact_code":"DYSPNOEA_ON_MINIMAL_EXERTION","expect":true}},{"type":"not","condition":{"type":"boolean","fact_code":"DYSPNOEA_AT_REST","expect":true}}]}'::jsonb, '2', 'Symptoms on normal exertion, e.g. walking up a flight of stairs (HCH13-0003).', '11'),
   ('4336fa37-69bc-54b7-b829-e7499835b059', (SELECT id FROM knowledge.severity_score WHERE score_code = 'SCORE-NYHA'), 'NYHA-3', 'NYHA III - Symptoms on minimal exertion', '{"type":"and","conditions":[{"type":"boolean","fact_code":"DYSPNOEA_ON_MINIMAL_EXERTION","expect":true},{"type":"not","condition":{"type":"boolean","fact_code":"DYSPNOEA_AT_REST","expect":true}}]}'::jsonb, '3', 'Symptoms on minimal exertion, e.g. getting dressed (HCH13-0003).', '12'),
   ('500be39d-1be7-544c-ba49-16d9d2c56d10', (SELECT id FROM knowledge.severity_score WHERE score_code = 'SCORE-NYHA'), 'NYHA-4', 'NYHA IV - Symptoms at rest', '{"type":"boolean","fact_code":"DYSPNOEA_AT_REST","expect":true}'::jsonb, '4', 'Symptoms at rest (HCH13-0003).', '13')
INSERT INTO knowledge.severity_score_interpretation (id, score_id, min_score, max_score, severity_label, disposition, recommendation) VALUES
   ('e67158ca-36fa-5eb8-8d44-8773caa73037', (SELECT id FROM knowledge.severity_score WHERE score_code = 'SCORE-NYHA'), '1', '1', 'NYHA I - Asymptomatic', 'Outpatient', 'No symptoms on ordinary exertion; confirm cause (ischaemic/hypertensive/valvular), ECG, CXR, echo, BNP.'),
   ('2c4a1bb0-7c2e-5fe6-bcb2-f0da6b23325e', (SELECT id FROM knowledge.severity_score WHERE score_code = 'SCORE-NYHA'), '2', '2', 'NYHA II - Mild', 'Outpatient', 'Symptoms on normal exertion (stairs); institute disease-modifying therapy, monitor fluid status and weight.'),
   ('adbb2ebb-8882-5e91-aaa5-94127e4adb00', (SELECT id FROM knowledge.severity_score WHERE score_code = 'SCORE-NYHA'), '3', '3', 'NYHA III - Moderate', 'Refer', 'Symptoms on minimal exertion (dressing); refer for specialist review; optimise diuretic/ACE therapy.'),
   ('bba3f13c-f9a7-554f-bd10-11019f8c8977', (SELECT id FROM knowledge.severity_score WHERE score_code = 'SCORE-NYHA'), '4', '4', 'NYHA IV - Severe', 'Refer', 'Symptoms at rest; urgent referral/admission; acute decompensation pathway with oxygen, ECG, CXR, echo, BNP.')
