   ('150462ed-34e3-51a5-b9f0-2124fefbad01', (SELECT ao.id FROM knowledge.answer_option ao JOIN knowledge.question q ON q.id = ao.question_id WHERE q.question_code = 'DYSPNOEA_SEVERITY' AND ao.answer_code = 'ON_EXERTION'), 'DYSPNOEA_ON_NORMAL_EXERTION', 'true', true),
   ('cc01dfd4-c3bf-59db-8b58-6c2923417db3', (SELECT ao.id FROM knowledge.answer_option ao JOIN knowledge.question q ON q.id = ao.question_id WHERE q.question_code = 'DYSPNOEA_SEVERITY' AND ao.answer_code = 'ON_WALKING'), 'DYSPNOEA_ON_MINIMAL_EXERTION', 'true', true),
