INSERT INTO knowledge.investigation (id, concept_id, investigation_code, canonical_name, description, investigation_type, body_system_code, specimen, turn_around_minutes, preparation, status) VALUES
   ('98ec1390-5382-5045-89b6-b521886920fd', NULL, 'INV-ECG', '12-lead ECG', '12-lead electrocardiogram - in heart failure usually abnormal: Q waves (previous MI), left ventricular hypertrophy, left bundle branch block or dysrhythmia; in cardiogenic shock may show recent infarction or dysrhythmia.', 'physiological', 'CARDIOVASCULAR', NULL, NULL, NULL, 'active'),
   ('5b4f78cc-3189-5e07-b0af-90b9f2217115', NULL, 'INV-ECHO', 'Echocardiogram', 'Echocardiography - the single most important diagnostic test in heart failure: shows left ventricular dilatation with regional (coronary heart disease) or global (cardiomyopathy) contractile impairment; excludes correctable valvular disease.', 'imaging', 'CARDIOVASCULAR', NULL, NULL, NULL, 'active'),
   ('b1cbe02b-1d42-553c-a101-bce75eed8c59', NULL, 'INV-BNP', 'B-type natriuretic peptide', 'B-type natriuretic peptide (BNP) - raised BNP is useful in cases of diagnostic uncertainty in heart failure.', 'laboratory', 'CARDIOVASCULAR', NULL, NULL, NULL, 'active'),
   ('ef4209c3-42fc-543a-b698-a3ff36b5603a', NULL, 'INV-TROPONIN', 'Cardiac troponin', 'Cardiac troponin - released when cardiac myocytes undergo ischaemic necrosis; measured in emergency chest pain/breathlessness; a negative result indicates the risk of a serious acute cardiac event in the ensuing 30 days is extremely low.', 'laboratory', 'CARDIOVASCULAR', NULL, NULL, NULL, 'active')
INSERT INTO knowledge.investigation_condition (id, investigation_id, condition_id, weight, rationale) VALUES
   ('acf000a6-7f25-5bee-a637-6dfce6b5fb8a', (SELECT id FROM knowledge.investigation WHERE investigation_code = 'INV-ECG'), (SELECT id FROM knowledge.condition WHERE condition_code = 'HEART_FAILURE'), '0.95', 'ECG usually abnormal in heart failure (HCH13-0002).'),
   ('49ea89e0-520d-5b33-bbc5-7f6298ba0acd', (SELECT id FROM knowledge.investigation WHERE investigation_code = 'INV-ECHO'), (SELECT id FROM knowledge.condition WHERE condition_code = 'HEART_FAILURE'), '0.95', 'Echo is the single most important diagnostic test in heart failure (HCH13-0002).'),
   ('4d92a314-d41b-56bd-ba0d-94bc79cefabc', (SELECT id FROM knowledge.investigation WHERE investigation_code = 'INV-BNP'), (SELECT id FROM knowledge.condition WHERE condition_code = 'HEART_FAILURE'), '0.85', 'Raised BNP useful in diagnostic uncertainty (HCH13-0002).'),
   ('43848ef4-73cd-5dcc-8f5b-3a09dfcb96f2', (SELECT id FROM knowledge.investigation WHERE investigation_code = 'INV-FBC'), (SELECT id FROM knowledge.condition WHERE condition_code = 'HEART_FAILURE'), '0.50', 'Blood count to rule out anaemia (HCH13-0002).'),
   ('3177e515-4f58-5e58-be1f-9082671d3c4e', (SELECT id FROM knowledge.investigation WHERE investigation_code = 'INV-ECG'), (SELECT id FROM knowledge.condition WHERE condition_code = 'COND-HF-DECOMPENSATION'), '0.95', 'ECG in acute decompensation may show MI, LBBB or dysrhythmia (HCH13-0002/0004).'),
   ('4189b02c-6466-51b1-893b-3949b7216dfa', (SELECT id FROM knowledge.investigation WHERE investigation_code = 'INV-CXR'), (SELECT id FROM knowledge.condition WHERE condition_code = 'COND-HF-DECOMPENSATION'), '0.95', 'CXR: cardiac enlargement, congested lung fields, bilateral perihilar air-space consolidation (HCH13-0002/0004, KCR-0019).'),
   ('b400db5d-2999-5d8b-8bd1-e0ea7d4e9677', (SELECT id FROM knowledge.investigation WHERE investigation_code = 'INV-ECHO'), (SELECT id FROM knowledge.condition WHERE condition_code = 'COND-HF-DECOMPENSATION'), '0.95', 'Echo confirms LV dilatation and contractile impairment; excludes correctable valvular disease (HCH13-0002/0004).'),
   ('4dc67709-9df3-5095-9a37-0d8d930d44e0', (SELECT id FROM knowledge.investigation WHERE investigation_code = 'INV-BNP'), (SELECT id FROM knowledge.condition WHERE condition_code = 'COND-HF-DECOMPENSATION'), '0.85', 'Raised BNP useful in diagnostic uncertainty (HCH13-0002).'),
   ('974a25e5-9b62-52b0-8ac3-c153b01310cb', (SELECT id FROM knowledge.investigation WHERE investigation_code = 'INV-TROPONIN'), (SELECT id FROM knowledge.condition WHERE condition_code = 'COND-HF-DECOMPENSATION'), '0.60', 'Troponin measured in emergency chest pain/breathlessness; negative result lowers 30-day acute cardiac risk (HCH9-0002).')
