   ('172e0c47-a3a3-5296-92b9-b6322e0031ea', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), (SELECT id FROM knowledge.condition WHERE condition_code = 'HEART_FAILURE'), false)
INSERT INTO knowledge.protocol_step (id, protocol_id, step_code, step_label, step_type, sequence_no, instruction, rationale, required) VALUES
   ('618e5360-a594-5e43-9f95-db338b4aad93', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), 'STEP-01', 'Confirm heart failure decompensation', 'eligibility', '10', 'Confirm acute decompensation of heart failure: worsening dyspnoea, orthopnoea, paroxysmal nocturnal dyspnoea, leg swelling/oedema, fatigue, on a background of ischaemic or hypertensive left ventricular disease (or known heart failure).', 'Congestion with or without low cardiac output characterises decompensation (HCH13-0001/0004/0005).', TRUE),
   ('549063c0-afd2-5188-8dde-635062955c18', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), 'STEP-02', 'Assess airway, breathing, circulation + severity', 'red_flag', '20', 'Rapid ABC assessment in a safe, monitored (ECG + pulse oximetry) environment; detect severe dyspnoea, orthopnoea, frothy sputum, low-output state (hypotension, oliguria, cold periphery), tachycardia, S3, sweating, crackles, cyanosis or narrow pulse pressure (cardiogenic shock).', 'Acute LVF and cardiogenic shock are emergencies (HCH13-0004, HCH9-0003).', TRUE),
   ('419e97fe-db8f-5995-8de6-bebacc1791e7', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), 'STEP-03', 'Position the patient upright and give oxygen', 'treatment', '30', 'Sit the patient upright. Administer high-flow oxygen unless there is good evidence it causes breathing difficulty (most commonly COPD); reassess frequently.', 'High-flow oxygen unless COPD is the immediate response to the distressed breathless patient (HCH9-0002).', TRUE),
   ('6c1bf955-13ed-54a4-a98e-c3feb41e1249', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), 'STEP-04', 'Obtain a 12-lead ECG', 'investigation', '40', 'Urgent 12-lead ECG: look for Q waves (previous MI), left ventricular hypertrophy, LBBB or dysrhythmia; in cardiogenic shock may show recent infarction or dysrhythmia.', 'ECG is urgent in the breathless patient and is usually abnormal in heart failure (HCH9-0002, HCH13-0002).', TRUE),
   ('e1c605e6-3b32-5fec-8e4e-4f961160fc32', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), 'STEP-05', 'Image the chest', 'investigation', '50', 'Chest X-ray: cardiac enlargement, congested lung fields, bilateral perihilar air-space consolidation; heart size should be <50% of thoracic width on PA film. Also excludes pneumothorax, pneumonia and large pleural effusions.', 'CXR is urgent and shows the congested cardiac pattern; cardiomegaly <50% thoracic width (HCH9-0002, HCH13-0002/0004, KCR-0019).', TRUE),
   ('c26fa153-2e9c-5b05-b07e-e4746d1b0eb9', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), 'STEP-06', 'Send BNP + renal function + blood count', 'investigation', '60', 'BNP (raised in diagnostic uncertainty), renal function as prelude to diuretic and ACE inhibitor therapy, and blood count to rule out anaemia.', 'BNP, renal function and FBC are the additional investigations in congestive heart failure (HCH13-0002).', TRUE),
   ('065559c1-3aa2-50c1-b6a7-eb401cc74242', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), 'STEP-07', 'Echocardiogram', 'investigation', '70', 'Echocardiogram - the single most important diagnostic test: LV dilatation with regional or global contractile impairment; exclude correctable valvular disease.', 'Echo confirms the diagnosis and guides therapy (HCH13-0002/0004).', TRUE),
   ('4736e9d9-35db-5efa-a1c4-38eac1d15a3e', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), 'STEP-08', 'Start diuretic + ACE inhibitor therapy (advice-level)', 'treatment', '80', 'Loop diuretic for congestion and an angiotensin converting enzyme (ACE) inhibitor once renal function is known; monitor weight, fluid balance, renal function and potassium. (Advice-level - verify doses against the local formulary.)', 'Renal function is the prelude to diuretic and ACE inhibitor therapy (HCH13-0002).', TRUE),
   ('3450e355-9cc7-5a39-a70b-50e87985bcdb', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), 'STEP-09', 'Monitor vital signs and daily weight', 'monitoring', '90', 'Monitor SpO2 (target according to comorbidity), heart rate, respiratory rate and daily body weight; track urine output and fluid balance.', 'Fluid retention tracking (daily weight) is central to decongestion in heart failure (HCH13-0005).', TRUE),
   ('78b2b3b2-3760-5e3a-846d-d59de76aec3a', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), 'STEP-10', 'Escalate if cardiogenic shock or deterioration', 'escalation', '100', 'If hypotension, oliguria, cool periphery, narrow pulse pressure or failure to improve: escalate urgently - inotropic support and invasive measures may be required; refer to critical care.', 'Cardiogenic shock requires inotropic support and invasive measures (HCH9-0003).', TRUE),
   ('53f9b70f-aa81-504b-9df5-f94796bc9f7e', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), 'STEP-11', 'Educate the patient and plan prevention', 'education', '110', 'Teach daily weight monitoring, salt/fluid restriction, medication adherence (diuretic + ACE inhibitor) and symptom recognition (orthopnoea, PND, leg swelling) with an action plan to seek care early.', 'Self-care reduces recurrent decompensation (HCH13-0005/0006).', TRUE),
   ('d7d447a9-18fa-5613-b207-80fb739c94c7', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), 'STEP-12', 'Close the care loop', 'follow_up', '120', 'Grade NYHA class (I-IV), document ECG/CXR/echo/BNP results, disposition, diuretic + ACE inhibitor plan and follow-up; reconsider the underlying cause (ischaemic, hypertensive, valvular, cardiomyopathy, alcohol).', 'Heart failure is chronic: the decompensation episode feeds ongoing maintenance and surveillance (HCH13-0002/0003).', TRUE)
