   ('8cb1f475-1589-5ac4-96d4-22ff23e9d2b5', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-HF-DECOMP' AND ps.step_code = 'STEP-01'), 'score', 'SCORE-NYHA', 'NYHA functional class', 'Grade NYHA I-IV from exertional symptom threshold (normal exertion / minimal exertion / at rest)', 'routine', '10'),
