   ('68eda89c-22a5-56b0-8ef5-e1e09d39665c', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-HF-DECOMP' AND ps.step_code = 'STEP-03'), 'advice', 'ADV-HF-POSITION', 'Sit the patient upright', 'Sitting upright reduces preload and work of breathing in pulmonary oedema', 'immediate', '10'),
   ('2a6e85fa-3a71-50d4-ae1c-f45e3698e001', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-HF-DECOMP' AND ps.step_code = 'STEP-03'), 'advice', 'ADV-HF-OXYGEN', 'High-flow oxygen unless COPD', 'High-flow O2 with reservoir unless known COPD / CO2 retention; reassess frequently', 'immediate', '20'),
   ('b67f2731-9a48-561e-937b-b445ce8ef3a5', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-HF-DECOMP' AND ps.step_code = 'STEP-04'), 'investigate', 'INV-ECG', '12-lead ECG', 'MI, LVH, LBBB, dysrhythmia; dynamic changes', 'urgent', '10'),
   ('6e3d87ac-e25f-504b-817a-7dee8af91386', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-HF-DECOMP' AND ps.step_code = 'STEP-05'), 'investigate', 'INV-CXR', 'Chest X-ray', 'Cardiac enlargement, congested lung fields, perihilar consolidation; exclude pneumothorax/effusion', 'urgent', '10'),
   ('eb35d4b6-b0e0-57c3-bee8-871b09ad64c9', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-HF-DECOMP' AND ps.step_code = 'STEP-06'), 'investigate', 'INV-BNP', 'B-type natriuretic peptide', 'Raised in heart failure; useful in diagnostic uncertainty', 'urgent', '10'),
   ('a9b7019c-3725-538e-b43d-fdb7fbaface4', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-HF-DECOMP' AND ps.step_code = 'STEP-06'), 'investigate', 'INV-UREA-CREAT', 'Renal function (urea/creatinine)', 'Prelude to diuretic + ACE inhibitor therapy', 'urgent', '20'),
   ('a7c9dffd-bb62-55a8-b599-ed25705066d6', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-HF-DECOMP' AND ps.step_code = 'STEP-06'), 'investigate', 'INV-FBC', 'Full blood count', 'Rule out anaemia as a driver of symptoms', 'routine', '30'),
   ('128075e9-438c-5151-a123-5d65f49d82dc', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-HF-DECOMP' AND ps.step_code = 'STEP-07'), 'investigate', 'INV-ECHO', 'Echocardiogram', 'Single most important test: LV dilatation + contractile impairment; exclude valvular disease', 'urgent', '10'),
   ('671cfbe0-f5fd-587a-bb1c-8847e702efb3', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-HF-DECOMP' AND ps.step_code = 'STEP-08'), 'advice', 'ADV-HF-DIURETIC', 'Loop diuretic (advice)', 'Loop diuretic for congestion once renal function known; monitor weight, fluid balance, electrolytes (advice-level - verify dose against local formulary)', 'urgent', '10'),
   ('d2bc03ee-aa1c-596e-b567-0fd65a6c34fa', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-HF-DECOMP' AND ps.step_code = 'STEP-08'), 'advice', 'ADV-HF-ACE', 'ACE inhibitor (advice)', 'ACE inhibitor once renal function known; monitor potassium and renal function (advice-level - verify dose against local formulary)', 'urgent', '20'),
   ('296bf767-34ac-5b41-9242-d1965c060a89', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-HF-DECOMP' AND ps.step_code = 'STEP-09'), 'monitor', 'MON-WEIGHT', 'Daily body weight', 'Daily weight tracks fluid retention/decongestion in heart failure', 'routine', '10'),
   ('96582061-8a76-55ad-b795-c37bf7221aac', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-HF-DECOMP' AND ps.step_code = 'STEP-09'), 'monitor', 'MON-SPO2', 'Oxygen saturation monitoring', 'Target per comorbidity; avoid excessive O2 in COPD', 'routine', '20'),
   ('b129b56b-5e44-5156-9f02-d522ba6b69de', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-HF-DECOMP' AND ps.step_code = 'STEP-10'), 'refer', 'REF-CRITICAL-CARE', 'Critical care referral', 'Cardiogenic shock: inotropic support + invasive measures', 'immediate', '10'),
   ('3bb22072-5e2d-5cc7-8e14-421733e9b28b', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-HF-DECOMP' AND ps.step_code = 'STEP-10'), 'refer', 'REF-CARDIOLOGY', 'Cardiology review', 'Specialist review for echo-guided management and underlying cause', 'urgent', '20'),
   ('ce51f9e7-b015-5cfa-ab01-cd7cdcdb584e', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-HF-DECOMP' AND ps.step_code = 'STEP-11'), 'educate', 'EDU-HF-SELF-CARE', 'Heart failure self-care', 'Daily weight, salt/fluid restriction, medication adherence, early symptom recognition', 'routine', '10'),
   ('c9420de4-0b2e-5b17-8759-f1709a6525dc', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-HF-DECOMP' AND ps.step_code = 'STEP-11'), 'educate', 'EDU-HF-DIET', 'Salt and fluid restriction', 'Reduce sodium intake; monitor fluid balance to prevent fluid retention', 'routine', '20'),
   ('f5e7b472-5b49-5f07-ac8a-92e8a6f69c3d', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-HF-DECOMP' AND ps.step_code = 'STEP-11'), 'educate', 'EDU-HF-SYMPTOM-RECOGNITION', 'Symptom recognition and action plan', 'Seek care early for increasing orthopnoea, PND, leg swelling or weight gain', 'routine', '30'),
