INSERT INTO knowledge.protocol_monitoring (id, protocol_id, monitoring_id, frequency, deterioration_rule, escalation_instruction) VALUES
   ('9179464b-21f2-57a5-9ac9-5ca12e4ac6d1', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), (SELECT id FROM knowledge.monitoring WHERE monitoring_code = 'MON-SPO2'), 'Continuous during acute decompensation; target per comorbidity (avoid excessive O2 in COPD)', 'SpO2 <90% or falling despite oxygen, or rising work of breathing', 'Reassess severity; check ABG if available; escalate to critical care if cardiogenic shock'),
   ('3ac8e420-75c4-583d-8de0-f4038b0be53c', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), (SELECT id FROM knowledge.monitoring WHERE monitoring_code = 'MON-HR'), 'Continuous during acute decompensation', 'New dysrhythmia, uncontrolled tachycardia, or pulse deficit (AF)', 'Repeat ECG; senior/cardiology review'),
   ('76e28469-ffd0-540e-b1d1-c3c4b8c29b3f', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), (SELECT id FROM knowledge.monitoring WHERE monitoring_code = 'MON-RR'), 'Continuous during acute decompensation', 'Persistent tachypnoea or rising work of breathing', 'Reassess severity; consider CXR/ABG; escalate'),
   ('a5354e3f-afec-5a5c-8478-0d1fce4c048a', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-HF-DECOMP'), (SELECT id FROM knowledge.monitoring WHERE monitoring_code = 'MON-WEIGHT'), 'Daily', 'Rapid weight gain (>2 kg over 1-2 days) reflecting fluid retention', 'Review diuretic dose, fluid balance and renal function')
