INSERT INTO knowledge.education (id, concept_id, education_code, title, audience, content_type, language_code, literacy_level, body, status) VALUES
   ('81d00eb3-d5f0-5672-8d03-a44c59a75277', (SELECT id FROM knowledge.concept WHERE concept_code = 'CNS-EDU-HF-SELF-CARE'), 'EDU-HF-SELF-CARE', 'Heart failure self-care', 'patient', 'instruction', 'en', 'plain', 'Weigh yourself daily, restrict salt and fluid, take diuretic and ACE inhibitor medicines as prescribed, and seek care early for increasing orthopnoea, paroxysmal nocturnal dyspnoea, leg swelling or rapid weight gain (HCH13-0002/0005).', 'active'),
   ('80d83d55-ca49-5456-9b42-48fede479931', (SELECT id FROM knowledge.concept WHERE concept_code = 'CNS-EDU-HF-DIET'), 'EDU-HF-DIET', 'Salt and fluid restriction', 'patient', 'instruction', 'en', 'plain', 'Heart failure causes salt and water retention; reduce sodium intake and monitor fluid balance to prevent peripheral oedema and pulmonary congestion (HCH13-0005).', 'active'),
   ('57992246-3c25-5149-8ed2-9eafe984b6c8', (SELECT id FROM knowledge.concept WHERE concept_code = 'CNS-EDU-HF-SYMPTOM-RECOGNITION'), 'EDU-HF-SYMPTOM-RECOGNITION', 'Symptom recognition and action plan', 'caregiver', 'discharge', 'en', 'plain', 'Rising JVP, basal crackles, pitting ankle/sacral oedema and orthopnoea signal congestion; rapid weight gain is an early warning. Seek care early rather than waiting for breathlessness at rest (HCH13-0001/0006).', 'active'),
   ('bc76acc3-12c0-5712-816e-3c80757f364a', (SELECT id FROM knowledge.concept WHERE concept_code = 'CNS-EDU-HF-CLINICIAN'), 'EDU-HF-CLINICIAN', 'Heart failure reasoning summary', 'clinician', 'explanation', 'en', 'plain', 'Render NYHA class, ECG/CXR/echo/BNP evidence, diuretic + ACE inhibitor plan, escalation threshold (cardiogenic shock), disposition and follow-up.', 'active')
