INSERT INTO governance.knowledge_object (id, object_code, knowledge_type, canonical_name, description, source_claim_code, jurisdiction_code, population_code, evidence_level_code, lifecycle_status, confidence, is_active, status) VALUES
   ('395584bb-f50b-54a1-9f9e-674fff1a7f55', 'PROT-HF-DECOMP', 'PROTOCOL', 'Acute heart failure decompensation pathway', 'Population-aware adult acute heart failure decompensation pathway: confirm decompensation, ABC + severity, upright positioning + high-flow oxygen unless COPD, ECG, CXR, BNP + renal + FBC, echo, advice-level diuretic + ACE inhibitor, monitoring (SpO2/HR/RR/daily weight), cardiogenic shock escalation, education and NYHA grading.', 'HCH13-0002', 'JUR-GLOBAL', 'POP-ADULT', 'EV-C', 'ACTIVE', 0.95, true, 'active'),
   ('967dd91b-0168-5350-97b3-7c752810c789', 'SCORE-NYHA', 'INTERPRETATION', 'NYHA functional classification', 'NYHA I-IV functional class from exertional dyspnoea threshold (normal exertion / minimal exertion / at rest), per Hutchison 24e Table 13.2 (HCH13-0003).', 'HCH13-0003', 'JUR-GLOBAL', 'POP-ADULT', 'EV-C', 'ACTIVE', 0.95, true, 'active'),
   ('b1d955cb-5e8c-59d2-a2e2-10a23ae0b40c', 'PHEN-CHF-CONGESTIVE', 'PHENOTYPE', 'Cardiopulmonary congestion phenotype', 'Dyspnoea + orthopnoea + PND + peripheral oedema + crackles pattern suggesting congestive heart failure decompensation (HCH13-0001/0004/0005).', 'HCH13-0001', 'JUR-GLOBAL', 'POP-ADULT', 'EV-C', 'ACTIVE', 0.95, true, 'active')
